    await a.fiber.dispose()
    expect(controller.menu.getSnapshot().open).toBe(false)
    controller.track('/g', 2, { tier: 'plain' }, 1)
    expect(controller.menu.getSnapshot().open).toBe(false)

    const again = mint('a')
