    ca.track('/g', 2, { tier: 'plain' }, 1)
    expect(ca.menu.getSnapshot().open).toBe(true)
    expect(cb.menu.getSnapshot().open).toBe(false)

    src.pending[0]!.resolve([{ name: 'goal' }])
    await tick()
    expect(ca.menu.getSnapshot().groups[0]!.items).toEqual([{ name: 'goal' }])
